#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# SPDX-FileCopyrightText: © 2026 Tenstorrent USA, Inc.
#
# Apply a hash-pinned vllm-tt-plugin patch series to the plugin checkout in the
# current directory (stopgap: agentic-models QB2 CI, not for merge).
#
# Usage: apply_vllm_tt_plugin_series.sh <series-file>
#
# The series file is generated by the tt-metal carrier from agentic-models'
# patches.json and lives at ${TT_METAL_HOME}/agentic_models/ci/vllm_tt_plugin/series.
# Format, one record per line:
#   base <40-hex plugin commit>          first record; the checkout must be exactly this commit
#   <64-hex sha256> <patch file name>    then one line per patch, in apply order
# Patch file names are relative to the series file's directory and contain no
# whitespace. Blank lines and lines starting with '#' are ignored.
#
# Each patch is sha256-verified, checked with `git apply --check` against the tree
# left by the patches before it, then applied. Any mismatch fails the build.
set -euo pipefail

series="${1:?usage: $0 <series-file>}"
series_dir="$(cd "$(dirname "${series}")" && pwd)"
fail() { echo "vllm-tt-plugin series: $*" >&2; exit 1; }

base=""
count=0
while read -r first second rest || [ -n "${first:-}" ]; do
    case "${first:-}" in ''|'#'*) continue ;; esac
    [ -z "${rest:-}" ] || fail "malformed line: ${first} ${second} ${rest}"
    if [ -z "${base}" ]; then
        [ "${first}" = "base" ] && [[ "${second:-}" =~ ^[0-9a-f]{40}$ ]] \
            || fail "first record must be 'base <40-hex sha>', got: ${first} ${second:-}"
        base="${second}"
        plugin_head="$(git rev-parse HEAD)"
        [ "${plugin_head}" = "${base}" ] || fail "plugin HEAD ${plugin_head} != series base ${base}"
        continue
    fi
    [[ "${first}" =~ ^[0-9a-f]{64}$ ]] && [ -n "${second:-}" ] \
        || fail "malformed patch record: ${first} ${second:-}"
    case "${second}" in /*|*..*) fail "patch path must stay inside ${series_dir}: ${second}" ;; esac
    patch="${series_dir}/${second}"
    [ -f "${patch}" ] || fail "missing patch ${patch}"
    actual="$(sha256sum "${patch}" | cut -d' ' -f1)"
    [ "${actual}" = "${first}" ] || fail "sha256 mismatch for ${second}: ${actual} != ${first}"
    git apply --check "${patch}" || fail "${second} does not apply"
    git apply "${patch}"
    count=$((count + 1))
    echo "vllm-tt-plugin series: applied ${second} (${first})"
done < "${series}"

[ -n "${base}" ] || fail "${series} has no 'base' record"
echo "vllm-tt-plugin series: ${count} patch(es) applied on ${base}"
